// ─────────────────────────────────────────
// 전체게시판 HTML 파싱
// 에펨코리아 li.li_post 구조
// ─────────────────────────────────────────
const html = $input.first().json.data || '';

function extractPosts(html) {
  const posts = [];
  const liPattern = /<li[^>]*class="[^"]*li_post[^"]*"[^>]*>([\s\S]*?)<\/li>/gi;
  let match;
  while ((match = liPattern.exec(html)) !== null) {
    const block = match[1];
    const titleMatch = block.match(/class="[^"]*title[^"]*"[^>]*>[\s\S]*?<a[^>]*href="([^"]+)"[^>]*>([^<]+)</);
    if (!titleMatch) continue;
    const url = 'https://www.fmkorea.com' + titleMatch[1];
    const title = titleMatch[2].trim().replace(/\s+/g, ' ');
    const viewMatch = block.match(/조회[^\d]*(\d[\d,]*)/) || block.match(/(\d[\d,]*)\s*읽음/);
    const views = viewMatch ? parseInt(viewMatch[1].replace(/,/g, '')) : 0;
    const commentMatch = block.match(/\[(\d+)\]/);
    const comments = commentMatch ? parseInt(commentMatch[1]) : 0;
    const dateMatch = block.match(/(\d{4}\.\d{2}\.\d{2}|\d{2}\.\d{2}|\d+분 전|\d+시간 전|방금)/);
    const date = dateMatch ? dateMatch[1] : '';
    if (title.length > 2) posts.push({ title, url, views, comments, date, sentiment: 'pending' });
  }
  return posts;
}

const posts = extractPosts(html);
const totalMatch = html.match(/총\s*([\d,]+)\s*개/) || html.match(/전체\s*([\d,]+)/);
const total_posts = totalMatch ? parseInt(totalMatch[1].replace(/,/g, '')) : posts.length;
const total_views = posts.reduce((a, p) => a + p.views, 0);
const avg_views = posts.length > 0 ? Math.round(total_views / posts.length) : 0;

return [{
  json: {
    source: 'all',
    total_posts,
    total_views,
    avg_views_per_post: avg_views,
    posts,
    crawled_at: new Date().toISOString()
  }
}];

