// ─────────────────────────────────────────
// Claude API: 게시글 감성분석 + EA 리포트 형식 데이터 생성
// 전체게시판용
// ─────────────────────────────────────────
const data = $input.first().json;
const posts = data.posts.slice(0, 30);
const titlesText = posts.map((p, i) => `${i+1}. ${p.title}`).join('\n');

const prompt = `당신은 FC온라인 커뮤니티 분석 전문가입니다.
아래 게시글 제목들을 분석하여 JSON만 응답하세요. 다른 텍스트 없이 순수 JSON만.

게시글 제목:
${titlesText}

응답 형식:
{
  "sentiments": ["positive"|"neutral"|"negative", ...],
  "sentiment_summary": { "positive": 숫자(%), "neutral": 숫자(%), "negative": 숫자(%) },
  "top_issues": {
    "positive": "긍정 이슈 핵심 한 줄 (20자 이내)",
    "negative": "부정 이슈 핵심 한 줄 (20자 이내)",
    "neutral": "중립 이슈 핵심 한 줄 (20자 이내)"
  },
  "keywords": [
    { "topic": "키워드명", "count": 추정언급수, "pct": "X.X%", "tags": "관련 서브키워드들" }
  ],
  "churn_signals": ["이탈/불만 신호 문장1", "문장2"],
  "impact_score": 4.0~6.0사이_소수점1자리
}`;

const response = await fetch('https://api.anthropic.com/v1/messages', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'x-api-key': $credentials.anthropicApiKey,
    'anthropic-version': '2023-06-01'
  },
  body: JSON.stringify({
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 2000,
    messages: [{ role: 'user', content: prompt }]
  })
});

const result = await response.json();
const raw = result.content[0].text.trim().replace(/```json|```/g, '').trim();

let analysis;
try { analysis = JSON.parse(raw); }
catch { analysis = { sentiments: posts.map(() => 'neutral'), sentiment_summary: { positive: 33, neutral: 34, negative: 33 }, top_issues: { positive: '분석 실패', negative: '분석 실패', neutral: '분석 실패' }, keywords: [], churn_signals: [], impact_score: 5.0 }; }

const updatedPosts = data.posts.map((p, i) => ({ ...p, sentiment: analysis.sentiments[i] || 'neutral' }));

const now = new Date();
const kstOffset = 9 * 60 * 60 * 1000;
const kst = new Date(now.getTime() + kstOffset);
const lastUpdated = kst.toISOString().replace('T', ' ').slice(0, 16);

return [{
  json: {
    ...data,
    posts: updatedPosts,
    sentiment: analysis.sentiment_summary,
    top_issues: analysis.top_issues,
    keywords: analysis.keywords,
    churn_signals: analysis.churn_signals,
    impact_score: analysis.impact_score,
    last_updated: lastUpdated
  }
}];

